package com.sumaye.restaurant.controller;
import com.sumaye.restaurant.dto.CustomerRequest; import com.sumaye.restaurant.model.Customer; import com.sumaye.restaurant.service.CustomerService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/branches/{branchId}/customers") @RequiredArgsConstructor public class CustomerController {private final CustomerService service;
 @GetMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER','CASHIER')") public Page<Customer> search(@PathVariable Long branchId,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.search(branchId,q,PageRequest.of(page,Math.min(size,100),Sort.by("fullName")));}
 @PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER')") public ResponseEntity<Customer> create(@PathVariable Long branchId,@Valid @RequestBody CustomerRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(branchId,r));}}
